{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_and_handles_empty():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False)] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_boundaries():
    assert flags_in_window([2, 0, 3], 1) == 3
    assert flags_in_window([2, 0, 3], 2) == 3
    assert flags_in_window([2, 0, 3], 0) == 0
    assert flags_in_window([2, 0, 3], 10) == 5
    assert flags_in_window([], 2) == 0


def test_parse_fields_and_skipped_lines():
    lines = ["  # comment,1,1", "", "  \t ", " x , 2 , 1 ", "y, -1, 0", "z, 3,   "]
    assert parse_transcript_log(lines) == [
        event("x", 2, True), event("y", -1, False), event("z", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["only,two", "a,1,1,extra", "a,not-a-day,1", "a,1,yes"])
def test_parse_error_has_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["# comment", "  ", bad_line])


def test_dedupe_duplicate_ids_keeps_last_then_sorts():
    earlier = event("a", 1, True)
    latest = event("a", 3, None)
    b = event("b", 2, True)
    c = event("c", 2, False)
    assert dedupe_transcripts([earlier, c, b, latest]) == [b, c, latest]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_include_empty_days_and_ignore_outside():
    events = [event("a", 0, True), event("b", 2, True), event("c", 2, True),
              event("d", 3, None), event("e", 4, False), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 2) == []


def test_monitor_summary_uses_calendar_days_weighted_rate_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 4, False), event("c", 4, None)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "a": [event("a", 1, True)],
              "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_and_empty_none():
    groups = {"z": [], "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_resets_and_requires_positive():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
